catalogDepletedDescriptor:
function catalogDepletedDescriptor(source,unit,depleted=false){
  if(!depleted||!unit)return source;
  const rate=unit?.UnitParam?.CollisionParam?.DepletionRate;
  const fieldRate=Number.isFinite(rate)&&rate>=0&&rate<=1?rate:1;
  const c={...source.c};
  for(const key of ['InitRadiusForPlayer','EndRadiusForPlayer','InitRadiusForField','EndRadiusForField']){
    if(Number.isFinite(c[key]))c[key]*=fieldRate;
  }
  const param=unit?.UnitParam?.PaintParam;
  const paintRate=Number.isFinite(param?.DepletionDepthWidthRate)?param.DepletionDepthWidthRate:1;
  const paint={...source.b?.PaintParam};
  for(const key of Object.keys(paint)){
    if((key.startsWith('WidthHalf')||key.startsWith('DepthScale'))&&Number.isFinite(paint[key]))
      paint[key]*=paintRate;
  }
  return {...source,depleted:true,c,b:{...source.b,CollisionParam:c,PaintParam:paint},
    radius:source.radius*paintRate};
}

paintStamp:
function paintStamp(rt, actor, point, radius, seed) {
  if (actor.remote || !rt.api.G.paint?.splat || !(radius > 0)) return 0;
  const at = rt.v4.copy(point), top = groundAt(rt, point, rt.v5);
  at.copy(top);
  const qRadius = Math.min(MAX_STAMP_RADIUS, radius), n = seedUnit(seed, 0);
  const area = rt.api.G.paint.splat(at, qRadius, actor.team, {
    seed: n, claimOwner: actor, claimMode: 'no-special',
  });
  if (finite(area) && area > 0) actor.addTurfNoSpecial?.(area);
  return finite(area) ? area : 0;
}

paintDiskCentres:
function paintDiskCentres(radius){
  const spacing=2.82,rowZ=spacing*Math.sqrt(3)/2;
  const maxCentre=Math.max(0,radius-MAX_STAMP_RADIUS),centres=[[0,0]];
  for(let row=-Math.ceil(maxCentre/rowZ);row<=Math.ceil(maxCentre/rowZ);row++){
    const z=row*rowZ,shift=row&1?spacing*.5:0;
    for(let col=-Math.ceil(maxCentre/spacing);col<=Math.ceil(maxCentre/spacing);col++){
      const x=col*spacing+shift;if((x||z)&&Math.hypot(x,z)<=maxCentre)centres.push([x,z]);
    }
  }
  if(maxCentre>0){// Doubling retains every previous angle; n-to-n+1 rephasing can remove painted cells.
    const count=6*2**Math.max(0,Math.ceil(Math.log2((2*Math.PI*maxCentre/spacing)/6)));for(let i=0;i<count;i++){const angle=2*Math.PI*i/count;centres.push([Math.cos(angle)*maxCentre,Math.sin(angle)*maxCentre]);}}
  return centres;
}

paintDiskLayout:
function paintDiskLayout(rt, point, radius, plan = null) {
  // Tile in the nearby contact plane. Keeping every tile at the same world Y
  // leaves large holes on slopes; projecting each tile from above can instead
  // jump between disconnected floors. The short probe avoids both mistakes.
  const normal=rt.up.clone(), from=point.clone();from.y+=.25;
  const contact=rt.api.G.physics?.raycast?.(from,rt.down,.5,rt.hit,true);
  if(contact?.hit&&contact.normal?.y>.4)normal.copy(contact.normal).normalize();
  const tangent=new rt.api.THREE.Vector3(1,0,0).addScaledVector(normal,-normal.x).normalize();
  const bitangent=new rt.api.THREE.Vector3().crossVectors(tangent,normal).normalize();
  // A constant-radius stamp must remain inside the nominal source disk.
  // An outer ring closes lattice scallops without placing stamp centres near R.
  // Reuse one mask seed so the R=3.74 transition cannot union unrelated shapes.
  const centres=plan || paintDiskCentres(radius);
  const seen=new Set(),tiles=[];
  for(const [x,z]of centres){
    const at=rt.v4.copy(point).addScaledVector(tangent,x).addScaledVector(bitangent,z);at.set(q2(at.x),q2(at.y),q2(at.z));
    const key=at.x+','+at.y+','+at.z;if(seen.has(key))continue;seen.add(key);tiles.push({x,z,key});
  }
  return {tangent,bitangent,tiles};
}

paintDiskTile:
function paintDiskTile(rt,actor,point,layout,tile,maskSeed){
  const at=rt.v4.copy(point).addScaledVector(layout.tangent,tile.x).addScaledVector(layout.bitangent,tile.z);
  at.set(q2(at.x),q2(at.y),q2(at.z));
  const got=rt.api.G.paint.splat(at,MAX_STAMP_RADIUS,actor.team,{seed:maskSeed,claimOwner:actor,claimMode:'no-special'});
  return finite(got)?got:0;
}

paintDisk:
function paintDisk(rt, actor, point, radius, seed, maskSeed = seedUnit(seed,0), alreadyPainted = null, plan = null) {
  if (radius <= MAX_STAMP_RADIUS) return paintStamp(rt, actor, point, radius, seed);
  // Cluster ordinary network-admissible stamps; do not emit one over-limit paint
  // row, which the public replication owner correctly rejects.
  const layout=paintDiskLayout(rt,point,radius,plan);let area=0;
  for(const tile of layout.tiles){if(alreadyPainted?.has(tile.key))continue;area+=paintDiskTile(rt,actor,point,layout,tile,maskSeed);}
  if (area > 0) actor.addTurfNoSpecial?.(area);
  return area;
}

paintBooyahGrowth:
function paintBooyahGrowth(rt,object,paintFrame,paintRadius,seed){
  const growthRadius=paintRadius*paintFrame/6;
  if(paintFrame===1){const area=paintStamp(rt,object.owner,object.pos,growthRadius,seed);object.paintFrame=paintFrame;object.paintedRadius=growthRadius;return area;}
  object.paintDiskTiles||=new Set();
  if(!object.paintDiskPlan||object.paintDiskPlan.radius!==paintRadius)
    object.paintDiskPlan={radius:paintRadius,centres:paintDiskCentres(paintRadius)};
  const plan=object.paintDiskPlan.centres;
  const layout=paintDiskLayout(rt,object.pos,paintRadius,plan),maskSeed=seedUnit(seed,0),limit=growthRadius-MAX_STAMP_RADIUS;
  let area=0;
  for(const tile of layout.tiles){
    if(object.paintDiskTiles.has(tile.key)||Math.hypot(tile.x,tile.z)>limit+1e-8)continue;
    area+=paintDiskTile(rt,object.owner,object.pos,layout,tile,maskSeed);object.paintDiskTiles.add(tile.key);
  }
  if(area>0)object.owner.addTurfNoSpecial?.(area);
  object.paintFrame=paintFrame;object.paintedRadius=growthRadius;
  if(paintFrame===6)paintDisk(rt,object.owner,object.pos,paintRadius,seed,maskSeed,object.paintDiskTiles,plan);
  return area;
}

emitArrow:
function emitArrow(runner,r,charge) {
    const a=runner.a,p=r.parameters.spl__WeaponStringerParam,t=p.ShotParam||{}, frames=charge*chargeFrames(r), count=finite(t.ArrowNum,3);
    // Unlike damage/speed, ArrowAngleMax is the uncharged angle; Min is
    // the fully charged angle. The sparse Tri-Stringer zero is a local default.
    const degrees=stageValue(r,{ArrowAngleMin:finite(t.ArrowAngleMax,8),
      ArrowAngleMid:finite(t.ArrowAngleMid,8),ArrowAngleMax:finite(t.ArrowAngleMin,0)},'ArrowAngle',frames,8);
    const desc=mode(r,'arrow',0,charge),s=state(runner),flight=addedFamilySplash(desc.b,r.family,s.arrowShotOrdinal||0);
    if(flight)Object.assign(desc,{splashDropSpec:flight.spec,splashFirst:flight.first,
      splashSpacing:flight.spacing,splashCount:flight.count});
    origin(a);const at=muzzle.clone(), direction=dir.clone();
    const tilt=state(runner).bowTilt*RAD;
    const right=new THREE.Vector3(direction.z,0,-direction.x);
    if(right.lengthSq()<EPS)right.set(1,0,0);else right.normalize();
    const up=new THREE.Vector3().crossVectors(direction,right).normalize();
    const spreadAxis=right.multiplyScalar(Math.cos(tilt)).addScaledVector(up,Math.sin(tilt));
    for(let i=0;i<count;i++) {
      const off=(i-(count-1)/2)*degrees;
      const aim=direction.clone().multiplyScalar(Math.cos(off*RAD)).addScaledVector(spreadAxis,Math.sin(off*RAD));
      const birth=at.clone().addScaledVector(spreadAxis,(i-(count-1)/2)*finite(t.ArrowMargin,0));
      // Separated nocks must obey the same muzzle obstruction guard.
      constrainMuzzle(G.physics,at,birth);
      spawn(a,r,desc,aim,birth,{index:i,bowTilt:s.bowTilt});
    }
    s.arrowShotOrdinal=(s.arrowShotOrdinal||0)+1;
    notify(a,r,at,direction,charge);
  }

ShapePool:
class ShapePool {
  constructor(THREE, name, geometry, cap, attrs, vert, frag, additive, uTime, extra = {}, light = {}) {
    this.cap = cap; this.recs = []; this.attrs = attrs; this._emptyUploaded = false;
    const g = new THREE.InstancedBufferGeometry();
    for (const key of Object.keys(geometry.attributes)) g.setAttribute(key, geometry.attributes[key]);
    if (geometry.index) g.setIndex(geometry.index);
    this.buf = attrs.map(name => { const b = new THREE.InstancedBufferAttribute(new Float32Array(cap * 4), 4).setUsage(THREE.DynamicDrawUsage); g.setAttribute(name, b); return b; });
    g.instanceCount = 1;
    const m = new THREE.ShaderMaterial({ uniforms: { uTime, uAdd: { value: additive ? 1 : 0 }, ...light }, vertexShader: vert, fragmentShader: frag,
      transparent: true, depthWrite: false, side: extra.side ?? THREE.DoubleSide, blending: additive ? THREE.CustomBlending : THREE.NormalBlending });
    if (additive) { m.blendSrc = THREE.OneFactor; m.blendDst = THREE.OneFactor; m.blendSrcAlpha = THREE.ZeroFactor; m.blendDstAlpha = THREE.OneFactor; }
    this.mesh = new THREE.Mesh(g, m); this.mesh.frustumCulled = false; this.mesh.renderOrder = extra.order ?? (additive ? 8 : 5); this.mesh.name = 'special-vfx:' + name;
    geometry.dispose?.();
  }
  _retire(record) {
    if (record.retired) return;
    record.retired = true;
    const finish = record.onEnd; record.onEnd = null;
    if (finish) finish();
  }
  add(life, values, follow = null) {
    if (this.recs.length >= this.cap - 1) this._retire(this.recs.shift());
    const rec = { v: new Float32Array(16), t: 0, life, follow, dead: false };
    rec.v.set(values);
    this.recs.push(rec);
    return rec;
  }
  update(dt) {
    if(this.recs.length===0&&this._emptyUploaded)return;
    for (let i = this.recs.length - 1; i >= 0; i--) {
      const r = this.recs[i]; r.t += dt;
      if (r.dead || (r.life > 0 && r.t >= r.life) || (r.follow && r.follow(r, dt) === false)) { this.recs.splice(i, 1); this._retire(r); }
    }
    const n = this.recs.length;
    for (let k = 0; k < this.buf.length; k++) {
      const A = this.buf[k].array;
      A[0] = A[1] = A[2] = A[3] = 0;
      for (let j = 0; j < n; j++) { const v = this.recs[j].v; const o = (j + 1) * 4, s = k * 4; A[o] = v[s]; A[o + 1] = v[s + 1]; A[o + 2] = v[s + 2]; A[o + 3] = v[s + 3]; }
      this.buf[k].clearUpdateRanges(); this.buf[k].addUpdateRange(0, (n + 1) * 4); this.buf[k].needsUpdate = true;
    }
    // degenerate warm instance: alpha 0
    const col = this.buf[2].array; col[3] = 0;
    this.mesh.geometry.instanceCount = n + 1;this._emptyUploaded=n===0;this._drawCount=n;
  }
  clear() { for (const r of this.recs) this._retire(r); this.recs.length = 0; this._emptyUploaded = false; }
}

throwVolley:
function throwVolley(System, actor, descriptor) {
  const count = VOLLEY_CONFIG.lobes;
  // The camera-ray aim path, exactly as the native shooter uses it: the muzzle
  // anchor from native `_muzzle`, the 3D direction from native `_aimFrom` (which
  // falls back to aimDir when the aim point is too close or behind). The
  // Trizooka is NOT a lobbed bomb, so the native bomb throw tilt, pitch clamp and
  // carry term are deliberately NOT used here.
  // The scratch vectors come from the native pool, so no new vector type and no
  // extra import is needed.
  const seed = System._new();
  const muzzle = System._muzzle(actor, seed.pos);
  const aim = System._aimFrom(actor, muzzle, seed.vel).clone();
  const fired = [];
  const volleyDamage = new Map();
  for (let i = 0; i < count; i++) {
    const p = i === 0 ? seed : System._new();
    const spread = VOLLEY_CONFIG.spreadDeg * Math.PI / 180;
    // The calibrated fan stays symmetric about lobe 0. Authority is independent
    // of that visual/aim index: all three local globs are full Trizooka rounds.
    const k = i === VOLLEY_CONFIG.damageLobeIndex ? 0 : (i === 1 ? -1 : 1);
    const vol = System.vols ? System.vols[System.volI = (System.volI + 1) % System.vols.length] : null;
    if (vol) vol.hits.length = 0;
    Object.assign(p, {
      type: descriptor.type,
      wid: descriptor.wid,                    // native cause id, used by ghost restore
      owner: actor,
      team: actor.team,
      age: 0,
      delay: i * VOLLEY_CONFIG.lobeInterval,
      s3TrizookaBirthPending: i > 0,
      s3TrizookaBirthLife: trizookaBirthLife(actor),
      s3TrizookaBirthOwner: actor.owner,
      s3TrizookaBirthRemote: !!actor.remote,
      life: TRIZOOKA.duration,
      straight: TRIZOOKA.goStraightFrames,
      damage: descriptor.directDamage,
      damageOwner: true,
      radius: descriptor.impactRadius,
      size: 0.22,
      grav: descriptor.grav,
      drag: descriptor.drag,
      vol,
      s3TrizookaVolleyDamage: volleyDamage,
      trail: -1.5,
      trailEvery: 1.1,
      trailRadius: 0.3,
      seed: (i * 0.37 + 0.11) % 1,
    });
    // the ONLY deviation from the native aim ray is the calibrated lateral lobe
    // fan: the native `_spread` is random, this one is deterministic so a volley
    // is reproducible and so a test can assert the carrier is on the ray
    const lateral = perpendicularBasis(aim);
    p.vel.copy(aim).addScaledVector(lateral.u, Math.sin(k * spread))
      .normalize().multiplyScalar(TRIZOOKA.spawnSpeed);
    p.pos.copy(muzzle);
    p.prev.copy(p.pos); p.start.copy(p.pos);
    p.s3SpecialWeapon = descriptor;            // parent preserves this before _push
    p.s3Weapon = descriptor;
    p.s3VolleyIndex = i;
    p.s3SizeBase = p.size;             // the native sweep grows on top of this
    p.s3Yaw = actor.aimYaw;               // stable orbit basis before the first step
    p.s3ActionIndex = descriptor.actionIndex ?? 0;
    p.ghost = false;
    System._push(p);                           // the one native list, the one native record
    fired.push(p);
  }
  return fired;
}

poseSubModel:
function poseSubModel(model, s = {}) {
  if (!model) return;
  const g = model.groups, st = model.state, dt = Number.isFinite(s.dt) ? Math.max(0, Math.min(0.25, s.dt)) : 0;
  st.t += dt;
  switch (model.id) {
    case 'autobomb': {
      const v = Number.isFinite(s.speed) ? s.speed : 0;
      st.stride = (st.stride || 0) + dt * v * 9;
      const k = Math.min(1, v / 1.5), sw = Math.sin(st.stride) * 0.5 * k;
      if (g.legL) g.legL.rotation.x = sw;
      if (g.legR) g.legR.rotation.x = -sw;
      if (g.body) g.body.position.y = Math.abs(Math.cos(st.stride)) * 0.012 * k;
      break;
    }
    case 'torpedo':
      if (g.prop) g.prop.rotation.z += dt * (s.flying === false ? 4 : 40);
      break;
    case 'sprinkler':
      if (g.head && Number.isFinite(s.spin)) g.head.rotation.y = s.spin;
      break;
    case 'beakon':
      if (g.dish) g.dish.rotation.y += dt * (s.active === false ? 0 : 1.1);
      break;
    case 'splashWall': {
      const u = Number.isFinite(s.unfold) ? Math.min(1, Math.max(0, s.unfold)) : 1;
      const arms = smoothstep(u * 1.6 - 0.6), grow = smoothstep(u * 1.4);
      model.root.scale.setScalar(SPLASH_WALL_FOLDED_SCALE + (1 - SPLASH_WALL_FOLDED_SCALE) * grow);
      // Folded (S3 icon): arms drawn in and pointing up in a bundle about the
      // tank's length, lower rod telescoped up toward the tank.
      const reach = 0.38 + 0.62 * arms;
      if (g.armR) { g.armR.rotation.z = (1 - arms) * Math.PI * 0.48; g.armR.scale.x = reach; }
      if (g.armL) { g.armL.rotation.z = -(1 - arms) * Math.PI * 0.48; g.armL.scale.x = reach; }
      if (g.leg) g.leg.scale.y = 0.42 + 0.58 * grow;
      if (g.curtain) {
        g.curtain.visible = u >= 0.999;
        const glow = model.materials.get('inkSheet');
        if (glow) glow.opacity = 0.18 + 0.06 * Math.sin(st.t * 23);
      }
      // Tank ink level follows the wall's remaining HP (presentation only).
      // Full is ~85% of the tank so the plunger and marks stay visible (refs).
      if (g.fill) g.fill.scale.y = 0.85 * Math.max(0.05, Number.isFinite(s.fill) ? Math.min(1, s.fill) : 1);
      break;
    }
    case 'inkMine':
      if (g.holo) {
        g.holo.visible = s.armed !== false;
        g.holo.rotation.y += dt * 0.6;
      }
      break;
    case 'fizzy': {
      const b = Number.isFinite(s.bulge) ? Math.min(1, Math.max(0, s.bulge)) : 0;
      if (g.body) g.body.scale.set(1 + 0.16 * b, 1 + 0.05 * b, 1 + 0.16 * b);
      break;
    }
    case 'toxicMistCloud':
      if (g.body) { g.body.rotation.y += dt * 0.35; g.body.scale.y = 1 + 0.04 * Math.sin(st.t * 1.7); }
      break;
    case 'spCrabTank': {
      // Crab Tank walk: the three legs a side swing about their hips in
      // alternating pairs with the ground speed (presentation only).
      const v = Number.isFinite(s.speed) ? s.speed : 0;
      st.stride = (st.stride || 0) + dt * v * 6;
      const k = Math.min(1, v / 2);
      for (let i = 0; i < 3; i++) {
        const [l, r] = CRAB_LEGS[i];
        if (g[l]) g[l].rotation.y = Math.sin(st.stride + i * 2.1) * 0.22 * k;
        if (g[r]) g[r].rotation.y = Math.sin(st.stride + i * 2.1 + Math.PI) * 0.22 * k;
      }
      break;
    }
    case 'pointSensor': {
      const m = model.materials.get('inkGlow');
      if (m) m.emissiveIntensity = 1 + 0.8 * (0.5 + 0.5 * Math.sin(st.t * 9));
      break;
    }
    default: break;
  }
}
